"""Assemble the adoption gate report from completed checks, never expected values."""
import re
from common import *
def main():
    repo=read(OUT/'repository_checks.json');package=read(OUT/'package_checks.json');equality=read(OUT/'derivation_equality.json');portable=read(OUT/'portability_check.json')
    words=[read(MANUSCRIPT/f'verification-{n}.json') for n in (1,2)]
    replay=read(OUT/'replay_comparisons.json');archive=read(OUT/'package_archive.json');summary=read(ROOT/'results/v17-summary-tables.json');tax=read(ROOT/'results/v17-residual-taxonomy.json')
    annotations=read(ROOT/'results/v17-failure-annotations-unified.json');unknown=[r['mutationId'] for r in annotations if r.get('causalMechanism')=='UNDETERMINED']
    gates={'C_rederived_equality':equality['allEqual'],'repository_twice':repo['completed'] and repo['allPassed'] and {r['pass'] for r in repo['commands']}=={1,2},'manuscript_twice':all(x['status']=='PASS' for x in words),'package_twice':package['completed'] and package['allPassed'] and len(package['rounds'])==2,'relocated_repository':portable['exitCode']==0,'two_actual_replays':all(r['status']=='EXECUTED' and r['comparison']['fullMatch'] for r in replay['subjects']),'identity_scan':read(OUT/'package_identity_scan.json')['zeroIdentityHits']}
    assert all(gates.values()),gates
    for file in ('preflight-C-1.log','preflight-C-2.log'):assert 'PASS: C raw-input' in (OUT/file).read_text()
    verification={'gates':gates,'status':'ALL_GATES_PASS','wordFiles':[{ 'path':str(MANUSCRIPT/n),'sha256':sha(MANUSCRIPT/n)} for n in ('RAD1_v16.docx','V16_CHANGES.md','plain-text.diff','verification-1.json','verification-2.json')], 'zip':archive,'undeterminedAnnotations':unknown}
    write(OUT/'gates.json',verification)
    changes=read(MANUSCRIPT/'changes.json');write(OUT/'manuscript_checks.json',{'passes':[{k:v for k,v in w.items() if k!='claims'} for w in words],'changedLocations':[{'location':r['location'],'sources':r['sources']} for r in changes],'files':verification['wordFiles']})
    rows=['# C adoption report','','Status: all repository, manuscript and package gates pass. Publication receipt is recorded below after Git operations.','','## Provenance and limits','','Preflight: `preflight.json`; input ZIP digest verified before extraction. C verification passed twice before adoption edits (`preflight-C-1.log`, `preflight-C-2.log`). Main baseline and prior branch HEAD are preserved in that record. No frozen map, evaluator/selector logic, constructor predicate, leaf exclusion, or other-six-subject PIT matrix changed.','','`analysis/projects_v17.json` changes only the two PIT patterns. Eighteen independently regenerated result objects equal C exactly (`derivation_equality.json`); method kinds and publication metrics are additionally verified. No outcome was copied in place of derivation.','','Earlier B/C verifiers have historical HEAD/whole-tree assertions. They were checked at the preserved historical snapshot, not falsely claimed compatible with a new adoption HEAD. All current analysis verifiers and the new v17 verifier run against the adoption inputs. `portability_check.json` additionally proves the new verifier in a relocated copy.','','The original JGraphT effective mutator option is UNKNOWN: its retained Maven profile explicitly names DEFAULTS, while original XML/stdout show the implicit operator set. The manuscript therefore does not assert omission as directly proved for that run. Spring omission and both replacement executions are evidenced. See `provenance_review.json`. This limits the historical explanation, not the adopted C results. PetClinic original installed PIT/plugin versions and historical effective CPU counts remain UNKNOWN.','','One duplicate raw XML exceeds GitHub’s single-file limit. Its already-verified canonical gzip decompresses to exactly the same bytes/hash; raw XML remains untouched locally and is not staged. `storage_manifest.json` records the lossless transport; the fresh-root verifier succeeds without that duplicate.','','## Adopted results','', '| Policy | Inclusive / eligible | Percent |','|---|---:|---:|']
    for p,v in summary['aggregate'].items():rows.append(f"| {p} | {v['inclusive']:,} / {v['eligible']:,} | {v['inclusivenessPctFullPrecision']:.2f}% |")
    rows+=['',f"Residual footprints: {tax['residualFootprintCounts']}. Causes: {tax['residualCausalMechanismCounts']}. UNDETERMINED annotations: {len(unknown)}.",'','Java: `results/v17-java-comparison.json`; recorded unchanged-selector full sets are reused only for identical map/class/method inputs, with newly derived occurrence weights. No new selector execution is claimed.','','## Checks, two passes','','| Pass | Check | Exit | Last line |','|---|---|---:|---|']
    for r in repo['commands']:rows.append(f"| {r['pass']} | {r['name']} | {r['exitCode']} | {r['lastLine']} |")
    rows+=['','Full commands, scopes, timing and logs: `repository_checks.json`. Each unittest pass ran '+re.search(r'Ran (\d+) tests',(OUT/'verification/pass-1-unittest.log').read_text()).group(1)+' tests. Historical B is explicitly scoped to its unmodified worktree.','','## Manuscript','','Word and full sentence/cell change list remain outside the evaluation repository:']
    for f in verification['wordFiles']:rows += ['',f"- `{f['path']}`; SHA-256 `{f['sha256']}`."]
    rows+=['',f"Each independent manuscript pass checks {words[0]['directDocumentClaimsChecked']} directly extracted claims; non-text OOXML properties are identical, five tables remain, Table 5 has seven rows, and all 22 references are unchanged. Tables 2 and 5 are byte-identical as XML. C’s 320-entry/66-change comparison was used as a cross-check, not a quota. `manuscript_checks.json` lists every changed location and source without exporting paper text.",'','The Word update also recalculates method kinds, rounded intervals/random values, run-2 means and changed class-selection count, and the 18-of-19 versus 761-of-3,931 mutator concentration. Java evidence reuse and historical-option uncertainty are stated precisely. No PDF or manuscript is committed.','','## Diagnostic replay','','Exactly the two authorized jobs ran once each; no full campaign or coverage collection ran.','','| Subject | Seconds | Records | Identity/status/killing-set matches | Inclusiveness changes |','|---|---:|---:|---|---|']
    for r in replay['subjects']:
        a=r['agreement'];rows.append(f"| {r['subject']} | {r['elapsedSeconds']:.2f} | {a['recordedRecords']}/{a['freshRecords']} | {a['matchingIdentities']}/{a['matchingStatuses']}/{a['matchingKillingSets']} | {a['inclusivenessChanges']} |")
    rows+=['','All PIT statuses, including timeouts/memory errors, remain visible. Both subject checkouts were restored clean. The six other replay directories are byte-identical to the input archive; Flink’s existing three killing-set differences remain observed without an invented cause. `replays.json` records CPU samples (no processor-count override), and `replay_comparisons.json` records all comparison fields.','','## Anonymous package','','Runner fix: native Spring `pitClasspath` is used; fallback registration is guarded. Four regression tests cover native/fallback task and environment handling. The worked-example evidence locator now uses the same XML ordinal directly rather than an old path suffix; selector logic and mutation identities are unchanged.','','Two fresh extractions of the exact ZIP execute evaluator tests, runner tests, eight stored-XML comparisons, runner help/plans, both fresh-replay comparisons, and full reproduction. The second extraction additionally runs `--write` then `--verify`. Both reject deliberate result corruption. Commands/logs are in `package_checks.json`; input preservation and gzip-aware identity scan are recorded. Accepted source/schema identifiers are not renamed.','','Archive: `'+archive['path']+'`',f"Bytes: {archive['bytes']}; SHA-256 `{archive['sha256']}`.",'','The anonymous package is not added to this repository. A recoverable copy of the input archive is retained outside it.','','## Publication','','Publication occurs only after this report’s gates pass. The exact adoption/merge/tag/push receipt is recorded in `publication.json` and the final handoff; no previous tag is moved.']
    (OUT/'REPORT.md').write_text('\n'.join(rows)+'\n')
    print('PASS: all adoption gates; report generated')
if __name__=='__main__':main()
